// Outscraper обычно возвращает { data: [ [ {...компания...}, ... ] ] } для синхронного запроса,
// но структура может отличаться в зависимости от версии API — обрабатываем варианты защитно.
const resp = $input.first().json;
let list = [];
if (Array.isArray(resp.data) && resp.data.length && Array.isArray(resp.data[0])) {
  list = resp.data[0];
} else if (Array.isArray(resp.data)) {
  list = resp.data;
} else if (Array.isArray(resp)) {
  list = resp;
}

return list.map(c => ({
  json: {
    company: c.name || c.title || '—',
    site: c.site || c.website || '',
    industry: c.category || c.type || '',
    phone: c.phone || '',
    address: c.full_address || c.address || ''
  }
}));

const item = $input.first().json;
const content = item.choices?.[0]?.message?.content || item.content || '';
const company = $('По одной компании').item.json;

function grab(label, text) {
  const re = new RegExp(label + '\\s*:\\s*([\\s\\S]*?)(?=\\n[А-ЯЁA-Z][А-ЯЁA-Z \\(\\)0-9]*:|$)', 'i');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

const scoreRaw = grab('SCORE', content).replace(/[^0-9]/g, '');
const score = scoreRaw ? parseInt(scoreRaw, 10) : '';

return [{
  json: {
    company: grab('КОМПАНИЯ', content) || company.company,
    site: company.site,
    industry: grab('ОТРАСЛЬ', content) || company.industry,
    facts: grab('ФАКТЫ', content),
    score,
    scoreReason: grab('ПОЧЕМУ ТАКОЙ SCORE', content),
    hypothesis: grab('ГИПОТЕЗА \\(ПРОБЛЕМА\\)', content) || grab('ГИПОТЕЗА', content),
    solution: grab('ВОЗМОЖНОЕ РЕШЕНИЕ', content),
    hook: grab('ЗАЦЕПКА ДЛЯ ПЕРСОНАЛИЗАЦИИ', content),
    rawResponse: content
  }
}];

